<div class="card"><h2>Add schedule slot</h2><form method="post" class="grid formgrid"><input type="hidden" name="_csrf" value="<?=e($security->csrf())?>"><input type="hidden" name="action" value="save"><label>Channel<select name="youtube_channel_id"><?php foreach($channels as $c):?><option value="<?=e((string)$c['id'])?>"><?=e($c['channel_name'])?></option><?php endforeach;?></select></label><label>Day<select name="day_of_week"><?php foreach(['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'] as $i=>$d):?><option value="<?=$i?>"><?=e($d)?></option><?php endforeach;?></select></label><label>Time<input type="time" name="upload_time" required></label><label>Timezone<input name="timezone" value="<?=e($config['app']['timezone'])?>" required></label><button class="btn primary">Add slot</button></form></div><div class="card"><h2>Schedule</h2><table><tr><th>Channel</th><th>Day</th><th>Time</th><th>Timezone</th><th></th></tr><?php foreach($schedules as $s):?><tr><td><?=e($s['channel_name'])?></td><td><?=e(['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'][(int)$s['day_of_week']])?></td><td><?=e($s['upload_time'])?></td><td><?=e($s['timezone'])?></td><td><form method="post"><input type="hidden" name="_csrf" value="<?=e($security->csrf())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=e((string)$s['id'])?>"><button class="btn danger">Delete</button></form></td></tr><?php endforeach;?></table></div>
